/**
 * OCR J277 flashcards.
 *
 * `points` uses bare spec point codes; the build tool resolves them to full ids.
 * Backs are written as the answer that earns the mark, not as a paraphrase — the
 * wording is the thing being learned.
 */
export default [
  // --- 1.1 Systems architecture ---------------------------------------------
  { id: 'cs-c-0001', points: ['1.1.1a'], kind: 'list', front: 'What are the three stages of the fetch–decode–execute cycle?', back: 'Fetch, decode, execute.', items: ['Fetch — the next instruction is copied from memory into the CPU', 'Decode — the control unit works out what the instruction means', 'Execute — the instruction is carried out'] },
  { id: 'cs-c-0002', points: ['1.1.1a'], kind: 'recall', front: 'During the fetch stage, what happens to the program counter?', back: 'It is incremented, so it holds the address of the next instruction ready for the following cycle.', hint: 'It has to move on.' },
  { id: 'cs-c-0003', points: ['1.1.1b'], kind: 'definition', front: 'What does the ALU do?', back: 'Carries out all arithmetic (add, subtract) and logic (AND, OR, NOT, comparisons) operations.' },
  { id: 'cs-c-0004', points: ['1.1.1b'], kind: 'definition', front: 'What does the control unit (CU) do?', back: 'Decodes instructions and sends control signals to coordinate the other components of the CPU.' },
  { id: 'cs-c-0005', points: ['1.1.1b'], kind: 'definition', front: 'What is cache memory and why does it speed up the CPU?', back: 'Very fast memory inside or close to the CPU that holds frequently used instructions and data. It is faster to access than RAM, so the CPU spends less time waiting.' },
  { id: 'cs-c-0006', points: ['1.1.1c'], kind: 'definition', front: 'What does the MAR hold?', back: 'The address of the memory location being read from or written to.', hint: 'Memory Address Register.' },
  { id: 'cs-c-0007', points: ['1.1.1c'], kind: 'definition', front: 'What does the MDR hold?', back: 'The actual data or instruction that has been fetched from memory, or that is about to be written to memory.', hint: 'Memory Data Register.' },
  { id: 'cs-c-0008', points: ['1.1.1c'], kind: 'definition', front: 'What does the program counter (PC) hold?', back: 'The memory address of the next instruction to be fetched.' },
  { id: 'cs-c-0009', points: ['1.1.1c'], kind: 'definition', front: 'What does the accumulator hold?', back: 'The result of calculations carried out by the ALU.' },
  { id: 'cs-c-0010', points: ['1.1.1c'], kind: 'recall', front: 'What is the defining feature of Von Neumann architecture?', back: 'Instructions and data are stored together in the same memory, and the program is stored in memory rather than hard-wired.' },
  // --- 1.1.1 deep deck (booklet + worksheet 1) --------------------------------
  { id: 'cs-c-0151', points: ['1.1.1a'], kind: 'definition', front: 'State the purpose of the CPU. [1]', back: 'It processes instructions and data.', hint: 'Not "the brain". Not "stores data".' },
  { id: 'cs-c-0152', points: ['1.1.1a'], kind: 'recall', front: 'Describe what happens during the FETCH stage. [2]', back: 'The address in the program counter is copied to the MAR, and the instruction at that address is copied from memory into the MDR. The program counter is then incremented.', hint: 'Two clauses: where from, where to.' },
  { id: 'cs-c-0153', points: ['1.1.1a'], kind: 'recall', front: 'Describe what happens during the DECODE stage. [1]', back: 'The control unit works out what the instruction means — what operation is required and what data it needs.' },
  { id: 'cs-c-0154', points: ['1.1.1a'], kind: 'recall', front: 'Describe what happens during the EXECUTE stage. [1]', back: 'The instruction is carried out. If it is arithmetic or a comparison, the ALU does it and the result is placed in the accumulator.' },
  { id: 'cs-c-0155', points: ['1.1.1a'], kind: 'recall', front: 'Why is the program counter incremented during the fetch stage rather than after execution?', back: 'Because the instruction being executed may itself change the PC (a jump or branch). Incrementing afterwards would overwrite that new address and send the program to the wrong place.', hint: 'What if the instruction is a jump?' },
  { id: 'cs-c-0156', points: ['1.1.1a'], kind: 'recall', front: 'Why does the fetch–decode–execute cycle repeat continuously while the computer is on? [3]', back: 'A program is a list of many instructions and only one can be processed at a time, so the cycle repeats to work through them. Even when the computer looks idle the operating system is still issuing instructions, so it never stops until the machine is switched off.' },
  { id: 'cs-c-0157', points: ['1.1.1a'], kind: 'list', front: 'Name the six transfers in one full cycle, in order.', back: 'PC → MAR, PC incremented, memory → MDR, MDR → CU (decode), execute (ALU if needed), result → accumulator.', items: ['The PC holds the address of the next instruction', 'That address is copied into the MAR', 'The PC is incremented', 'The instruction at the MAR address is copied into the MDR', 'The CU decodes the instruction from the MDR', 'It is executed — the ALU carries out any arithmetic and the result goes to the accumulator'] },
  { id: 'cs-c-0158', points: ['1.1.1b'], kind: 'definition', front: 'What is a register?', back: 'A very small, very fast store inside the CPU that holds one value being worked on right now.' },
  { id: 'cs-c-0159', points: ['1.1.1b'], kind: 'list', front: 'Put these in order, fastest access first: RAM, cache, secondary storage, registers.', back: 'Registers, cache, RAM, secondary storage.', items: ['Registers — fastest, inside the CPU', 'Cache — very fast, inside or beside the CPU', 'RAM — main memory, slower', 'Secondary storage — slowest'] },
  { id: 'cs-c-0160', points: ['1.1.1b'], kind: 'recall', front: 'Cache is much faster than RAM. Why does a computer not simply use cache instead of all its RAM?', back: 'Cache is far more expensive per byte and physically bigger per byte of storage, so a machine with cache-only memory would cost far too much and hold far too little.' },
  { id: 'cs-c-0161', points: ['1.1.1b'], kind: 'recall', front: 'Tom says: "The CPU stores all of the data on my computer." Explain why Tom is wrong. [2]', back: 'The CPU processes instructions and data, it does not store them. Its registers and cache hold only the small amount of data in use at that instant; the computer’s data is stored in RAM while running and in secondary storage permanently.' },
  { id: 'cs-c-0162', points: ['1.1.1c'], kind: 'compare', front: 'MAR or MDR — which holds an address and which holds data?', back: 'MAR = Memory ADDRESS Register, holds an address. MDR = Memory DATA Register, holds the data or instruction.', hint: 'The clue is the middle word of the name.' },
  { id: 'cs-c-0163', points: ['1.1.1c'], kind: 'compare', front: 'Which of the four registers hold ADDRESSES and which hold DATA?', back: 'Addresses: program counter and MAR. Data: MDR and accumulator.', items: ['PC — address of the NEXT instruction', 'MAR — address about to be read from or written to', 'MDR — the actual instruction or data fetched', 'ACC — the result of an ALU calculation'] },
  { id: 'cs-c-0164', points: ['1.1.1c'], kind: 'definition', front: 'Explain the stored program concept. [2]', back: 'Program instructions and the data they use are stored together in the same main memory, and the instructions are fetched from there and executed one at a time — rather than the machine being hard-wired to do one job.', hint: 'Two halves: same memory, AND fetched one at a time.' },
  { id: 'cs-c-0165', points: ['1.1.1c'], kind: 'recall', front: 'How does the CPU know whether an address holds an instruction or data?', back: 'It cannot tell from the value itself. Whatever is fetched at the address in the program counter during the fetch stage is treated as an instruction; whatever that instruction then asks for is treated as data.' },
  { id: 'cs-c-0166', points: ['1.1.1c'], kind: 'recall', front: 'Which register is incremented during every fetch, and why?', back: 'The program counter, so that it points at the next instruction ready for the following cycle.' },
  { id: 'cs-c-0167', points: ['1.1.1c'], kind: 'recall', front: 'The PC holds 102, containing SUB 205. What is copied into the MAR, and what does the PC hold next?', back: 'The address 102 is copied into the MAR. The PC is incremented to 103.' },
  { id: 'cs-c-0168', points: ['1.1.1a', '1.1.1c'], kind: 'calculation', front: 'ACC holds 14. The CPU executes ADD 201, where address 201 holds 9, then SUB 202 where 202 holds 5. What is in the accumulator after each instruction?', back: 'After ADD 201: 23. After SUB 202: 18.', hint: 'ADD and SUB work on the value AT the address.' },
  { id: 'cs-c-0169', points: ['1.1.1a', '1.1.1c'], kind: 'recall', front: 'In a trace of LDA 200, ADD 201, SUB 202, STO 203, HLT — in which cycles is the ALU used, and why not in the others?', back: 'Only in the ADD and SUB cycles. LDA and STO just move a value between memory and the accumulator, and HLT stops the CPU — none of them involves arithmetic or logic.' },
  { id: 'cs-c-0170', points: ['1.1.1c'], kind: 'recall', front: 'What does STO 203 do to the accumulator?', back: 'Nothing — it copies the accumulator’s value into address 203. The accumulator still holds the same value afterwards.', hint: 'Copy, not move.' },
  { id: 'cs-c-0171', points: ['1.1.1b', '1.1.1c'], kind: 'recall', front: 'Odd one out, and why: ALU • Control Unit • Hard disk drive • Cache', back: 'Hard disk drive — it is secondary storage outside the CPU; the other three are all inside the CPU.' },
  { id: 'cs-c-0172', points: ['1.1.1b', '1.1.1c'], kind: 'recall', front: 'Odd one out, and why: MAR • MDR • Program Counter • ALU', back: 'The ALU — the other three are registers that hold a value; the ALU is a processing component that does arithmetic and logic.' },
  { id: 'cs-c-0173', points: ['1.1.1a'], kind: 'recall', front: 'Odd one out, and why: Fetch • Decode • Execute • Compile', back: 'Compile — the other three are the stages of the fetch–execute cycle. Compiling is translating source code, and happens before the program runs.' },
  { id: 'cs-c-0174', points: ['1.1.1b'], kind: 'recall', front: 'Explain one way cache improves the performance of the CPU. [2]', back: 'Cache holds frequently used instructions and data close to the CPU, and is much faster to access than RAM, so the CPU spends less time waiting for data and can execute more instructions per second.', hint: 'Fact plus effect. "Explain" always wants the effect.' },
  { id: 'cs-c-0175', points: ['1.1.1b'], kind: 'recall', front: 'What is wrong with saying cache stores "recently used" data?', back: 'The mark scheme wants FREQUENTLY used instructions and data — the point of cache is that the same things get reused, not simply that they were touched once.' },
  { id: 'cs-c-0011', points: ['1.1.2a'], kind: 'list', front: 'Name the three CPU characteristics that affect performance.', back: 'Clock speed, cache size and number of cores.', items: ['Clock speed — cycles per second', 'Cache size — how much fast memory is available', 'Number of cores — how many instructions can run at once'] },
  { id: 'cs-c-0012', points: ['1.1.2a'], kind: 'recall', front: 'Why does doubling the number of cores not double performance?', back: 'Software has to be written to split work across cores. If it cannot be parallelised, the extra cores sit idle.' },
  { id: 'cs-c-0013', points: ['1.1.2a'], kind: 'recall', front: 'A CPU runs at 3.2 GHz. What does that mean?', back: 'It performs 3.2 billion (3,200,000,000) fetch–decode–execute cycles every second.' },
  { id: 'cs-c-0014', points: ['1.1.3a'], kind: 'definition', front: 'What is an embedded system?', back: 'A computer built into a larger device to perform one dedicated task, rather than a general-purpose computer.' },
  { id: 'cs-c-0015', points: ['1.1.3a'], kind: 'list', front: 'Give four characteristics of embedded systems.', back: 'Dedicated to one task, low power, low cost, small, reliable, software usually stored in ROM and rarely changed.', items: ['Performs one dedicated task', 'Low power consumption', 'Small and cheap to produce', 'Very reliable — the program rarely changes'] },
  { id: 'cs-c-0016', points: ['1.1.3b'], kind: 'list', front: 'Give four examples of embedded systems.', back: 'Washing machine, microwave, traffic lights, engine management unit, dishwasher, digital camera.', items: ['Washing machine', 'Microwave', 'Traffic lights', 'Car engine management unit'] },

  // --- 1.2 Memory and storage ------------------------------------------------
  { id: 'cs-c-0017', points: ['1.2.1a'], kind: 'recall', front: 'Why is primary storage needed?', back: 'The CPU can only directly access data and instructions held in primary storage, so anything currently in use must be there.' },
  { id: 'cs-c-0018', points: ['1.2.1b'], kind: 'compare', front: 'Give three differences between RAM and ROM.', back: 'RAM is volatile, read/write, and large; ROM is non-volatile, read-only, and small.' },
  { id: 'cs-c-0019', points: ['1.2.1b'], kind: 'definition', front: 'What does "volatile" mean?', back: 'The contents are lost when power is switched off.' },
  { id: 'cs-c-0020', points: ['1.2.1c'], kind: 'recall', front: 'What is stored in ROM, and why does it have to be there?', back: 'The boot program (BIOS). It must be non-volatile so the computer has instructions to run the moment it is switched on, before the OS has loaded.' },
  { id: 'cs-c-0021', points: ['1.2.1d'], kind: 'recall', front: 'What is held in RAM while a computer is running?', back: 'The operating system, any open applications, and the data those applications are working on.' },
  { id: 'cs-c-0022', points: ['1.2.1e'], kind: 'definition', front: 'What is virtual memory?', back: 'An area of secondary storage used as though it were RAM when RAM is full. Data not currently needed is moved out to it, and moved back when required.' },
  { id: 'cs-c-0023', points: ['1.2.1e'], kind: 'recall', front: 'Why does heavy use of virtual memory slow a computer down?', back: 'Secondary storage is far slower than RAM, and constantly moving data back and forth (disk thrashing) means the CPU waits.' },
  { id: 'cs-c-0024', points: ['1.2.2a'], kind: 'recall', front: 'Why is secondary storage needed?', back: 'It is non-volatile, so programs and files are kept permanently when the power is off. RAM would lose them.' },
  { id: 'cs-c-0025', points: ['1.2.2b'], kind: 'recall', front: 'How does optical storage physically store data?', back: 'Pits and lands are burned into the surface of the disc and read by reflecting a laser off them.' },
  { id: 'cs-c-0026', points: ['1.2.2b'], kind: 'recall', front: 'How does magnetic storage physically store data?', back: 'Tiny areas of a spinning platter are magnetised in one direction or the other, and a moving read/write head detects the polarity.' },
  { id: 'cs-c-0027', points: ['1.2.2b'], kind: 'recall', front: 'How does solid state storage physically store data?', back: 'Electrical charge is trapped in flash memory cells. There are no moving parts.' },
  { id: 'cs-c-0028', points: ['1.2.2d'], kind: 'compare', front: 'Give two advantages of an SSD over an HDD.', back: 'Faster read/write speeds, no moving parts so more durable and shock-resistant, silent, lower power consumption.' },
  { id: 'cs-c-0029', points: ['1.2.2d'], kind: 'compare', front: 'Give two advantages of an HDD over an SSD.', back: 'Cheaper per gigabyte, and available in larger capacities for the same money.' },
  { id: 'cs-c-0030', points: ['1.2.2d'], kind: 'list', front: 'Name the six factors used to compare storage devices.', back: 'Capacity, speed, portability, durability, reliability, cost.', items: ['Capacity', 'Speed', 'Portability', 'Durability', 'Reliability', 'Cost'] },
  { id: 'cs-c-0031', points: ['1.2.3a'], kind: 'list', front: 'List the units of data storage in order, smallest first.', back: 'Bit, nibble, byte, kilobyte, megabyte, gigabyte, terabyte, petabyte.', items: ['Bit (1)', 'Nibble (4 bits)', 'Byte (8 bits)', 'Kilobyte', 'Megabyte', 'Gigabyte', 'Terabyte', 'Petabyte'] },
  { id: 'cs-c-0032', points: ['1.2.3a'], kind: 'recall', front: 'How many bits in a nibble, and how many in a byte?', back: '4 bits in a nibble, 8 bits in a byte.' },
  { id: 'cs-c-0033', points: ['1.2.3c'], kind: 'calculation', front: 'What is the formula for the file size of a bitmap image?', back: 'File size (bits) = width × height × colour depth', hint: 'Three things multiplied.' },
  { id: 'cs-c-0034', points: ['1.2.3c'], kind: 'calculation', front: 'What is the formula for the file size of a sound file?', back: 'File size (bits) = sample rate × duration (seconds) × bit depth' },
  { id: 'cs-c-0035', points: ['1.2.4a'], kind: 'list', front: 'What are the 8-bit binary place values?', back: '128, 64, 32, 16, 8, 4, 2, 1', items: ['128', '64', '32', '16', '8', '4', '2', '1'] },
  { id: 'cs-c-0036', points: ['1.2.4a'], kind: 'calculation', front: 'Convert 10110101 to denary.', back: '181 — that is 128 + 32 + 16 + 4 + 1' },
  { id: 'cs-c-0037', points: ['1.2.4a'], kind: 'calculation', front: 'Convert denary 200 to 8-bit binary.', back: '11001000 — 128 + 64 + 8' },
  { id: 'cs-c-0038', points: ['1.2.4a'], kind: 'recall', front: 'How do you convert binary to hexadecimal?', back: 'Split the binary into nibbles of 4 bits from the right, then convert each nibble separately into one hex digit.' },
  { id: 'cs-c-0039', points: ['1.2.4a'], kind: 'calculation', front: 'What is hexadecimal 2F in denary?', back: '47 — (2 × 16) + 15' },
  { id: 'cs-c-0040', points: ['1.2.4a'], kind: 'recall', front: 'Why is hexadecimal used instead of binary?', back: 'It is much shorter, so it is easier for people to read, write and remember, and less prone to mistakes. It converts easily to binary because one hex digit is exactly four bits.' },
  { id: 'cs-c-0041', points: ['1.2.4b'], kind: 'definition', front: 'What is a binary overflow error?', back: 'When the result of a calculation needs more bits than are available, so the carry out of the most significant bit is lost and the answer is wrong.' },
  { id: 'cs-c-0042', points: ['1.2.4c'], kind: 'recall', front: 'What does a left shift of 2 places do to a binary number?', back: 'Multiplies it by 4 (2²). Zeros are added on the right.' },
  { id: 'cs-c-0043', points: ['1.2.4c'], kind: 'recall', front: 'What does a right shift of 3 places do, and what is the risk?', back: 'Divides by 8 (2³). Bits shifted off the right-hand end are lost, so precision can be lost.' },
  { id: 'cs-c-0044', points: ['1.2.4d'], kind: 'definition', front: 'What is a character set?', back: 'An agreed list of characters, each assigned a unique binary code, so that text can be represented and exchanged between systems.' },
  { id: 'cs-c-0045', points: ['1.2.4e'], kind: 'recall', front: 'How many characters can be represented with n bits?', back: '2ⁿ characters.' },
  { id: 'cs-c-0046', points: ['1.2.4e'], kind: 'compare', front: 'Compare ASCII and Unicode.', back: 'ASCII uses 7 bits, giving 128 characters — enough for English only. Unicode uses more bits per character, so it can represent every writing system in the world plus emoji, but the files are larger.' },
  { id: 'cs-c-0047', points: ['1.2.4f'], kind: 'definition', front: 'What is metadata in an image file?', back: 'Data about the image stored alongside the pixel data — width, height, colour depth, file type — needed to rebuild the image correctly.' },
  { id: 'cs-c-0048', points: ['1.2.4g'], kind: 'definition', front: 'What is colour depth?', back: 'The number of bits used to store the colour of each pixel. More bits means more possible colours.' },
  { id: 'cs-c-0049', points: ['1.2.4g'], kind: 'definition', front: 'What is image resolution?', back: 'The number of pixels in the image, usually given as width × height. More pixels means more detail and a bigger file.' },
  { id: 'cs-c-0050', points: ['1.2.4h'], kind: 'definition', front: 'How is analogue sound converted to digital?', back: 'The amplitude of the sound wave is measured (sampled) at regular intervals, and each measurement is stored as a binary number.' },
  { id: 'cs-c-0051', points: ['1.2.4i'], kind: 'recall', front: 'What effect does increasing the sample rate have?', back: 'The recording is closer to the original sound, so playback quality is better — but the file is larger.' },
  { id: 'cs-c-0052', points: ['1.2.4i'], kind: 'definition', front: 'What is bit depth in a sound file?', back: 'The number of bits used to store each sample. Higher bit depth means each measurement is more accurate.' },
  { id: 'cs-c-0053', points: ['1.2.5a'], kind: 'list', front: 'Give three reasons compression is needed.', back: 'Files transfer faster, use less bandwidth, and take up less storage space.', items: ['Faster to transmit / download', 'Uses less bandwidth', 'Takes up less storage space'] },
  { id: 'cs-c-0054', points: ['1.2.5b'], kind: 'compare', front: 'Compare lossy and lossless compression.', back: 'Lossy permanently removes data, giving much smaller files but reduced quality — used for images, audio and video. Lossless records patterns so the original can be restored exactly — used where every bit matters, such as text and program files.' },
  { id: 'cs-c-0055', points: ['1.2.5b'], kind: 'recall', front: 'Why must a text document use lossless compression?', back: 'Removing data would remove characters, changing the meaning. The original must be perfectly recoverable.' },

  // --- 1.3 Networks ----------------------------------------------------------
  { id: 'cs-c-0056', points: ['1.3.1a'], kind: 'compare', front: 'What is the difference between a LAN and a WAN?', back: 'A LAN covers a small geographical area and the infrastructure is owned by the organisation. A WAN covers a large area and the infrastructure is hired from a third party.' },
  { id: 'cs-c-0057', points: ['1.3.1b'], kind: 'list', front: 'Give four factors that affect network performance.', back: 'Bandwidth, number of users, transmission media, interference, error rate, latency.', items: ['Bandwidth available', 'Number of users on the network', 'Type of transmission media (fibre vs copper vs wireless)', 'Interference and signal strength'] },
  { id: 'cs-c-0058', points: ['1.3.1c'], kind: 'compare', front: 'Compare client–server and peer-to-peer networks.', back: 'Client–server: a central server holds files and manages security, so backups and updates are centralised — but the server is a single point of failure and is expensive. Peer-to-peer: every computer is equal and shares directly, cheaper and no server needed — but files are scattered and harder to back up or secure.' },
  { id: 'cs-c-0059', points: ['1.3.1d'], kind: 'definition', front: 'What does a switch do?', back: 'Connects devices within a LAN and sends data only to the specific device it is addressed to, using MAC addresses.' },
  { id: 'cs-c-0060', points: ['1.3.1d'], kind: 'definition', front: 'What does a router do?', back: 'Connects different networks together and directs data packets between them along the best route, using IP addresses.' },
  { id: 'cs-c-0061', points: ['1.3.1d'], kind: 'definition', front: 'What is a NIC?', back: 'Network Interface Card — the hardware inside a device that lets it connect to a network. It holds the device\'s MAC address.' },
  { id: 'cs-c-0062', points: ['1.3.1e'], kind: 'definition', front: 'What does DNS do?', back: 'Translates a human-readable domain name (like bbc.co.uk) into the IP address of the server hosting it, so the browser knows where to send the request.' },
  { id: 'cs-c-0063', points: ['1.3.1e'], kind: 'definition', front: 'What is "the cloud"?', back: 'Storage and processing provided on remote servers accessed over the internet, rather than on local hardware.' },
  { id: 'cs-c-0064', points: ['1.3.1f'], kind: 'compare', front: 'Compare star and mesh topologies.', back: 'Star: every node connects to a central switch — fast, easy to add devices, and one cable failure affects only one device, but the central switch is a single point of failure. Mesh: nodes connect to each other with multiple routes — very resilient with no single point of failure, but expensive and complex to cable.' },
  { id: 'cs-c-0065', points: ['1.3.2a'], kind: 'compare', front: 'Give two advantages of wired over wireless connections.', back: 'Faster and more reliable (less interference), and more secure because data cannot be intercepted from outside the building.' },
  { id: 'cs-c-0066', points: ['1.3.2b'], kind: 'definition', front: 'What is encryption and why is it used on networks?', back: 'Data is scrambled using a key so it becomes meaningless cipher text. If it is intercepted, it cannot be understood without the key.' },
  { id: 'cs-c-0067', points: ['1.3.2c'], kind: 'compare', front: 'What is the difference between an IP address and a MAC address?', back: 'An IP address identifies a device on a network and can change when it moves network. A MAC address is assigned to the NIC by the manufacturer and does not change.' },
  { id: 'cs-c-0068', points: ['1.3.2d'], kind: 'definition', front: 'What is a network standard, and why does it matter?', back: 'An agreed set of rules that all manufacturers follow, so hardware and software from different companies can work together.' },
  { id: 'cs-c-0069', points: ['1.3.2e'], kind: 'list', front: 'What do HTTP, HTTPS and FTP each do?', back: 'HTTP transfers web pages; HTTPS does the same but encrypted; FTP transfers files between computers.', items: ['HTTP — transfers web pages', 'HTTPS — transfers web pages securely (encrypted)', 'FTP — transfers files'] },
  { id: 'cs-c-0070', points: ['1.3.2e'], kind: 'compare', front: 'What is the difference between POP and IMAP?', back: 'POP downloads email to one device and usually deletes it from the server. IMAP leaves email on the server and syncs it across all devices.' },
  { id: 'cs-c-0071', points: ['1.3.2e'], kind: 'recall', front: 'What does SMTP do?', back: 'Sends email from a client to a mail server, and between mail servers.' },
  { id: 'cs-c-0072', points: ['1.3.2f'], kind: 'recall', front: 'Give two advantages of dividing network protocols into layers.', back: 'Each layer is self-contained, so it can be developed or changed without affecting the others. It also makes faults easier to find, because you can narrow the problem to one layer.' },

  // --- 1.4 Network security --------------------------------------------------
  { id: 'cs-c-0073', points: ['1.4.1a'], kind: 'compare', front: 'What is the difference between a virus and a worm?', back: 'A virus attaches itself to a file and needs the user to run that file to spread. A worm spreads by itself across a network without any user action.' },
  { id: 'cs-c-0074', points: ['1.4.1a'], kind: 'definition', front: 'What is a trojan?', back: 'Malware disguised as a legitimate, useful program. The user installs it themselves, and it then does damage.' },
  { id: 'cs-c-0075', points: ['1.4.1a'], kind: 'definition', front: 'What is ransomware?', back: 'Malware that encrypts the victim\'s files and demands payment in exchange for the decryption key.' },
  { id: 'cs-c-0076', points: ['1.4.1a'], kind: 'definition', front: 'What is spyware?', back: 'Malware that secretly monitors what the user does and sends the information back to the attacker.' },
  { id: 'cs-c-0077', points: ['1.4.1b'], kind: 'definition', front: 'What is social engineering?', back: 'Manipulating people into giving away confidential information or access, rather than attacking the technology. People are the weak point.' },
  { id: 'cs-c-0078', points: ['1.4.1b'], kind: 'definition', front: 'What is phishing?', back: 'Sending fake emails or messages that appear to come from a trusted organisation, to trick the victim into revealing passwords or bank details.' },
  { id: 'cs-c-0079', points: ['1.4.1c'], kind: 'definition', front: 'What is a brute-force attack?', back: 'Trying every possible combination of characters until the correct password is found, usually automated.' },
  { id: 'cs-c-0080', points: ['1.4.1d'], kind: 'definition', front: 'What is a denial of service (DoS) attack?', back: 'Flooding a server with so many requests that it cannot respond to legitimate users, so the service goes down.' },
  { id: 'cs-c-0081', points: ['1.4.1e'], kind: 'definition', front: 'What is data interception and theft?', back: 'Capturing data as it travels across a network — for example by packet sniffing on an unsecured Wi-Fi network — in order to steal it.' },
  { id: 'cs-c-0082', points: ['1.4.1f'], kind: 'definition', front: 'What is SQL injection?', back: 'Typing SQL code into an input box on a website so that it is executed by the database, letting the attacker read, change or delete data they should not be able to access.' },
  { id: 'cs-c-0083', points: ['1.4.2a'], kind: 'definition', front: 'What is penetration testing?', back: 'Deliberately attacking your own system, with permission, to find vulnerabilities before a real attacker does.' },
  { id: 'cs-c-0084', points: ['1.4.2b'], kind: 'definition', front: 'What does a firewall do?', back: 'Inspects traffic entering and leaving a network and blocks anything that does not meet the security rules.' },
  { id: 'cs-c-0085', points: ['1.4.2c'], kind: 'definition', front: 'What are user access levels, and why are they used?', back: 'Different users are given different permissions, so each person can only see and change what their role requires. This limits the damage a compromised account can do.' },
  { id: 'cs-c-0086', points: ['1.4.2d'], kind: 'list', front: 'Give three examples of physical security.', back: 'Locked server rooms, CCTV, security guards, keycard or biometric entry.', items: ['Locks on server room doors', 'CCTV', 'Keycard or biometric entry systems'] },

  // --- 1.5 Systems software --------------------------------------------------
  { id: 'cs-c-0087', points: ['1.5.1a', '1.5.1b', '1.5.1c', '1.5.1d', '1.5.1e'], kind: 'list', front: 'Name the five functions of an operating system.', back: 'User interface, memory management and multitasking, peripheral management and drivers, user management, file management.', items: ['User interface', 'Memory management and multitasking', 'Peripheral management and drivers', 'User management', 'File management'] },
  { id: 'cs-c-0088', points: ['1.5.1b'], kind: 'recall', front: 'What does memory management do?', back: 'Decides where in RAM each program and its data is placed, keeps programs from overwriting each other, and moves data to virtual memory when RAM is full.' },
  { id: 'cs-c-0089', points: ['1.5.1c'], kind: 'definition', front: 'What is a device driver?', back: 'Software that translates between the operating system and a specific piece of hardware, so the OS can control it without knowing its details.' },
  { id: 'cs-c-0090', points: ['1.5.2b'], kind: 'recall', front: 'What does defragmentation do, and why does it help?', back: 'Moves the scattered parts of split files back together so they are stored contiguously. The read/write head then moves less, so files load faster.' },
  { id: 'cs-c-0091', points: ['1.5.2b'], kind: 'recall', front: 'Why is defragmentation pointless on an SSD?', back: 'An SSD has no moving read/write head, so where data sits makes no difference to access speed — and the extra writes shorten its life.' },

  // --- 1.6 Impacts -----------------------------------------------------------
  { id: 'cs-c-0092', points: ['1.6.1b'], kind: 'recall', front: 'What does the Data Protection Act 2018 require of organisations?', back: 'Personal data must be used fairly and lawfully, kept accurate and secure, collected only for a stated purpose, kept no longer than necessary, and individuals have the right to see the data held about them.' },
  { id: 'cs-c-0093', points: ['1.6.1c'], kind: 'list', front: 'What are the three offences under the Computer Misuse Act 1990?', back: 'Unauthorised access; unauthorised access with intent to commit a further offence; unauthorised modification of material.', items: ['Unauthorised access to computer material', 'Unauthorised access with intent to commit a further offence', 'Unauthorised modification of computer material'] },
  { id: 'cs-c-0094', points: ['1.6.1d'], kind: 'recall', front: 'What does the Copyright, Designs and Patents Act 1988 protect?', back: 'The creator\'s ownership of original work — software, music, images, text — making it illegal to copy, distribute or adapt it without permission.' },
  { id: 'cs-c-0095', points: ['1.6.1e'], kind: 'compare', front: 'Compare open source and proprietary software.', back: 'Open source: source code is published, anyone can modify and share it, usually free, supported by the community. Proprietary: source code is kept secret, you buy a licence to use it, you cannot modify it, but you get official support and it is usually more polished.' },

  // --- 2.1 Algorithms --------------------------------------------------------
  { id: 'cs-c-0096', points: ['2.1.1a'], kind: 'definition', front: 'What is abstraction?', back: 'Removing unnecessary detail from a problem so you can focus only on what matters to solving it.' },
  { id: 'cs-c-0097', points: ['2.1.1b'], kind: 'definition', front: 'What is decomposition?', back: 'Breaking a large problem down into smaller sub-problems that can each be solved separately.' },
  { id: 'cs-c-0098', points: ['2.1.1c'], kind: 'definition', front: 'What is algorithmic thinking?', back: 'Working out the step-by-step sequence of instructions needed to solve a problem, so it can be repeated reliably.' },
  { id: 'cs-c-0099', points: ['2.1.2c'], kind: 'list', front: 'What do the flowchart shapes mean?', back: 'Rounded rectangle = start/stop, parallelogram = input/output, rectangle = process, diamond = decision.', items: ['Rounded rectangle — start or stop', 'Parallelogram — input or output', 'Rectangle — process', 'Diamond — decision', 'Rectangle with double side bars — sub program'] },
  { id: 'cs-c-0100', points: ['2.1.2e'], kind: 'recall', front: 'How do you fill in a trace table?', back: 'One column per variable (plus one for any output). Work through the algorithm line by line, writing a new row every time a variable changes.' },
  { id: 'cs-c-0101', points: ['2.1.3a'], kind: 'recall', front: 'How does a binary search work, and what must be true first?', back: 'The list must be sorted. Check the middle item; if it is not the target, discard the half that cannot contain it and repeat on the remaining half.' },
  { id: 'cs-c-0102', points: ['2.1.3a', '2.1.3b'], kind: 'compare', front: 'Compare binary and linear search.', back: 'Binary search is much faster on large lists but requires sorted data. Linear search is slower but works on unsorted data and is simpler to program.' },
  { id: 'cs-c-0103', points: ['2.1.3c'], kind: 'recall', front: 'How does a bubble sort work?', back: 'Compare each adjacent pair of items and swap them if they are in the wrong order. Repeat the pass through the list until a complete pass makes no swaps.' },
  { id: 'cs-c-0104', points: ['2.1.3d'], kind: 'recall', front: 'How does a merge sort work?', back: 'Repeatedly split the list in half until every list contains a single item, then repeatedly merge pairs of lists back together in the correct order.' },
  { id: 'cs-c-0105', points: ['2.1.3e'], kind: 'recall', front: 'How does an insertion sort work?', back: 'Take each item in turn and insert it into its correct position among the items already sorted, shifting the larger ones along.' },
  { id: 'cs-c-0106', points: ['2.1.3c', '2.1.3d'], kind: 'compare', front: 'Why is merge sort faster than bubble sort on large lists?', back: 'Merge sort repeatedly halves the problem, so the work grows far more slowly as the list gets longer. Bubble sort compares every pair repeatedly.' },

  // --- 2.2 Programming fundamentals -----------------------------------------
  { id: 'cs-c-0107', points: ['2.2.1a'], kind: 'compare', front: 'What is the difference between a variable and a constant?', back: 'A variable\'s value can change while the program runs; a constant is set once and cannot be changed.' },
  { id: 'cs-c-0108', points: ['2.2.1b', '2.2.1c', '2.2.1d'], kind: 'list', front: 'Name the three basic programming constructs.', back: 'Sequence, selection, iteration.', items: ['Sequence — instructions run one after another', 'Selection — a choice is made (if / else)', 'Iteration — instructions repeat (loops)'] },
  { id: 'cs-c-0109', points: ['2.2.1d'], kind: 'compare', front: 'What is the difference between count-controlled and condition-controlled iteration?', back: 'Count-controlled repeats a set number of times (a for loop). Condition-controlled repeats until a condition is met, which may be any number of times (while, do-until).' },
  { id: 'cs-c-0110', points: ['2.2.2a'], kind: 'list', front: 'Name the five data types you need for J277, with an example of each.', back: 'Integer (7), real/float (3.14), Boolean (True), character (\'a\'), string ("hello").', items: ['Integer — a whole number', 'Real / float — a number with a decimal part', 'Boolean — True or False', 'Character — a single character', 'String — a sequence of characters'] },
  { id: 'cs-c-0111', points: ['2.2.2b'], kind: 'recall', front: 'Why do you often need to cast the result of input()?', back: 'input() always returns a string. To do arithmetic with it you must cast it to an integer or real first, using int() or float().' },
  { id: 'cs-c-0112', points: ['2.2.3a'], kind: 'code', front: 'In Python, how do you get the length of a string and convert it to upper case?', back: 'len(name) gives the length; name.upper() gives the upper-case version.' },
  { id: 'cs-c-0113', points: ['2.2.3b'], kind: 'list', front: 'What are the four basic file handling operations?', back: 'Open, read, write, close.', items: ['Open the file', 'Read from it', 'Write to it', 'Close it'] },
  { id: 'cs-c-0114', points: ['2.2.3b'], kind: 'recall', front: 'Why must a file be closed after writing to it?', back: 'Closing flushes any buffered data to disk and releases the file, so data is not lost and other programs can access it.' },
  { id: 'cs-c-0115', points: ['2.2.3c'], kind: 'definition', front: 'What is a record?', back: 'A single data structure made up of several fields of different data types, describing one thing — like one student\'s name, age and form group.' },
  { id: 'cs-c-0116', points: ['2.2.3d'], kind: 'code', front: 'Write the SQL to get the name and grade of all students in form 10B.', back: 'SELECT name, grade FROM students WHERE form = \'10B\';', hint: 'SELECT … FROM … WHERE …' },
  { id: 'cs-c-0117', points: ['2.2.3e'], kind: 'recall', front: 'How do you access an item in a 2D array?', back: 'Give two indexes — the row and then the column, for example scores[2][1]. Both start at 0.' },
  { id: 'cs-c-0118', points: ['2.2.3f'], kind: 'compare', front: 'What is the difference between a function and a procedure?', back: 'A function returns a value to the code that called it. A procedure carries out a task but returns nothing.' },
  { id: 'cs-c-0119', points: ['2.2.3f'], kind: 'recall', front: 'Give two advantages of using sub programs.', back: 'Code can be reused instead of repeated, and the program is broken into smaller pieces that are easier to read, test and debug.' },
  { id: 'cs-c-0120', points: ['2.2.3g'], kind: 'code', front: 'In Python, how do you generate a random whole number from 1 to 6 inclusive?', back: 'import random, then random.randint(1, 6)' },

  // --- 2.3 Robust programs ---------------------------------------------------
  { id: 'cs-c-0121', points: ['2.3.1a'], kind: 'definition', front: 'What does "anticipating misuse" mean in defensive design?', back: 'Assuming users will enter the wrong thing — deliberately or by accident — and writing the program so it handles that without crashing.' },
  { id: 'cs-c-0122', points: ['2.3.1c'], kind: 'list', front: 'Name five types of input validation check.', back: 'Range check, type check, presence check, length check, format check.', items: ['Range check — is the value between sensible limits?', 'Type check — is it the right data type?', 'Presence check — has anything been entered at all?', 'Length check — is it the right number of characters?', 'Format check — does it match the required pattern?'] },
  { id: 'cs-c-0123', points: ['2.3.1c'], kind: 'recall', front: 'What is the difference between validation and verification?', back: 'Validation checks that data is sensible and in the right form. Verification checks that data has been entered accurately, for example by asking for a password twice.' },
  { id: 'cs-c-0124', points: ['2.3.1d'], kind: 'list', front: 'Give four things that make a program maintainable.', back: 'Sub programs, meaningful variable names, consistent indentation, comments.', items: ['Sub programs to break the code up', 'Meaningful naming conventions', 'Consistent indentation', 'Comments explaining the tricky parts'] },
  { id: 'cs-c-0125', points: ['2.3.2b'], kind: 'compare', front: 'What is the difference between iterative and final testing?', back: 'Iterative testing happens repeatedly during development, testing each part as it is written. Final (terminal) testing happens at the end on the complete program, against the original requirements.' },
  { id: 'cs-c-0126', points: ['2.3.2c'], kind: 'compare', front: 'What is the difference between a syntax error and a logic error?', back: 'A syntax error breaks the rules of the language, so the program will not run at all. A logic error runs fine but produces the wrong result.' },
  { id: 'cs-c-0127', points: ['2.3.2d'], kind: 'list', front: 'Name the four types of test data.', back: 'Normal, boundary, invalid, erroneous.', items: ['Normal — typical data that should be accepted', 'Boundary — data right at the edge of what is allowed', 'Invalid — right type but outside the allowed range', 'Erroneous — the wrong data type entirely'] },
  { id: 'cs-c-0128', points: ['2.3.2d'], kind: 'recall', front: 'A program accepts ages 11 to 18. Give one boundary, one invalid and one erroneous test value.', back: 'Boundary: 11 or 18. Invalid: 10 or 19 (a number, but out of range). Erroneous: "cat" (not a number at all).' },

  // --- 2.4 Boolean logic -----------------------------------------------------
  { id: 'cs-c-0129', points: ['2.4.1a'], kind: 'recall', front: 'When is the output of an AND gate 1?', back: 'Only when both inputs are 1.' },
  { id: 'cs-c-0130', points: ['2.4.1a'], kind: 'recall', front: 'When is the output of an OR gate 1?', back: 'When at least one input is 1.' },
  { id: 'cs-c-0131', points: ['2.4.1a'], kind: 'recall', front: 'What does a NOT gate do?', back: 'Inverts the input — a 1 becomes 0 and a 0 becomes 1.' },
  { id: 'cs-c-0132', points: ['2.4.1b'], kind: 'calculation', front: 'How many rows does a truth table with 3 inputs have?', back: '8 rows — 2³.' },
  { id: 'cs-c-0133', points: ['2.4.1c'], kind: 'recall', front: 'What are the symbols for AND, OR and NOT?', back: 'AND is ∧ (or a dot), OR is ∨ (or a plus), NOT is ¬ (or an overbar).' },

  // --- 2.5 Languages and IDEs ------------------------------------------------
  { id: 'cs-c-0134', points: ['2.5.1a'], kind: 'compare', front: 'Compare high-level and low-level programming languages.', back: 'High-level is close to English, machine independent, and quick to write and debug — but must be translated. Low-level is close to machine code, machine specific, and harder to write — but gives direct hardware control and efficient use of memory.' },
  { id: 'cs-c-0135', points: ['2.5.1b'], kind: 'recall', front: 'What is the purpose of a translator?', back: 'To convert source code written by a programmer into machine code that the CPU can execute.' },
  { id: 'cs-c-0136', points: ['2.5.1c'], kind: 'compare', front: 'Compare a compiler and an interpreter.', back: 'A compiler translates the whole program at once into an executable, reports all errors at the end, and the compiled program then runs quickly. An interpreter translates and runs one line at a time, stops at the first error, is easier to debug, but runs more slowly.' },
  { id: 'cs-c-0137', points: ['2.5.2a'], kind: 'list', front: 'Name four tools found in an IDE.', back: 'Editor, error diagnostics, run-time environment, translator.', items: ['Editor — with syntax highlighting and auto-complete', 'Error diagnostics — breakpoints, stepping, variable watch', 'Run-time environment — run the program without leaving the IDE', 'Translator — compiler or interpreter built in'] },
// --- gap fill: points not otherwise carded --------------------------------
  { id: 'cs-c-0138', points: ['1.2.2c'], kind: 'recall', front: 'A film crew needs to carry 4 TB of footage between locations, quickly and safely. Which storage would you choose and why?', back: 'A portable SSD — high capacity, fast transfer, and no moving parts so it survives being carried around. An HDD would be cheaper but is easily damaged by knocks; optical discs do not hold nearly enough.' },
  { id: 'cs-c-0139', points: ['1.2.3b'], kind: 'recall', front: 'Why must all data be converted to binary before a computer can process it?', back: 'Computer circuits only have two states — on and off, high and low voltage — so every instruction and every piece of data has to be represented as 1s and 0s.' },
  { id: 'cs-c-0140', points: ['1.5.2a'], kind: 'definition', front: 'What is utility software for?', back: 'It performs maintenance tasks that keep the computer running well — housekeeping rather than doing the user\'s actual work.' },
  { id: 'cs-c-0141', points: ['1.6.1a'], kind: 'list', front: 'What are the five impact categories you must consider for the 8-mark question?', back: 'Ethical, legal, cultural, environmental, privacy.', items: ['Ethical — is it the right thing to do?', 'Legal — does it break the law?', 'Cultural — how does it change how groups of people live?', 'Environmental — energy use, raw materials, e-waste', 'Privacy — what happens to people\'s data?'] },
  { id: 'cs-c-0142', points: ['1.6.1a'], kind: 'recall', front: 'Give two environmental impacts of digital technology.', back: 'Data centres and devices consume large amounts of electricity; manufacturing needs rare metals mined destructively; discarded devices create toxic e-waste.' },
  { id: 'cs-c-0143', points: ['2.1.2a'], kind: 'recall', front: 'For a program that works out a pupil\'s average test score, what are the inputs, processes and outputs?', back: 'Inputs: the individual test scores. Processes: add the scores, divide by how many there are. Output: the average score.' },
  { id: 'cs-c-0144', points: ['2.1.2b'], kind: 'definition', front: 'What is a structure diagram?', back: 'A hierarchical diagram showing a problem broken down into sub-problems, with the whole task at the top and increasingly specific tasks below it.' },
  { id: 'cs-c-0145', points: ['2.1.2d'], kind: 'list', front: 'What common errors should you look for when checking an algorithm?', back: 'Loops that run one time too many or too few, wrong comparison operators, variables not initialised, and conditions the wrong way round.', items: ['Off-by-one errors in loops', 'Using > where >= was needed', 'A variable used before it is given a value', 'Assignment (=) where comparison (==) was meant'] },
  { id: 'cs-c-0146', points: ['2.3.1b'], kind: 'definition', front: 'What is authentication, and give two examples.', back: 'Confirming that a user is who they claim to be before granting access. Examples: username and password, two-factor authentication, biometrics such as a fingerprint.' },
  { id: 'cs-c-0147', points: ['2.3.2a'], kind: 'recall', front: 'What is the purpose of testing a program?', back: 'To find and remove errors before release, and to check that the program meets its requirements and behaves correctly for every kind of input.' },
  { id: 'cs-c-0148', points: ['2.3.2e'], kind: 'recall', front: 'Give two ways an algorithm might be refined after testing.', back: 'Make it more efficient (fewer steps or less memory), make it more robust by adding validation, or make it more readable by splitting it into sub programs.' },
  { id: 'cs-c-0149', points: ['2.4.1d'], kind: 'calculation', front: 'An alarm sounds if the system is armed AND (a door is open OR a window is open). Write this as a Boolean expression using A, D and W.', back: 'A ∧ (D ∨ W)' },
  { id: 'cs-c-0150', points: ['2.4.1b', '2.4.1d'], kind: 'recall', front: 'How do you make sure you list every row of a truth table exactly once?', back: 'Count up in binary. With 3 inputs, go 000, 001, 010, 011, 100, 101, 110, 111.' },
  // --- 2.1.1 computational thinking + 2.1.2b structure diagrams (booklet Part 2)
  { id: 'cs-c-0176', points: ['2.1.1a'], kind: 'definition', front: 'Define the term abstraction. [2]', back: 'Removing or hiding detail that is not needed, so that only what matters for a particular purpose remains.', hint: 'Two marks: the removing, and the purpose.' },
  { id: 'cs-c-0177', points: ['2.1.1a'], kind: 'recall', front: 'Why is “abstraction means making something simpler” not good enough?', back: 'Because nothing is unnecessary in the abstract — it depends entirely on the purpose. The Tube map is a brilliant abstraction for choosing a train and a useless one for judging walking distance.' },
  { id: 'cs-c-0178', points: ['2.1.1a'], kind: 'recall', front: 'A Tube map: what is kept, what is removed, and what is it for?', back: 'Kept: the stations, the lines, the order of stops and the interchanges. Removed: real distances, real directions and the streets above. For: working out which train to take and where to change.' },
  { id: 'cs-c-0179', points: ['2.1.1a'], kind: 'recall', front: 'An app shows live bus arrival times at a chosen stop. Give two details of the real bus network the developers would abstract away.', back: 'Any two of: the make and colour of the buses, the drivers, the exact roads taken between stops, traffic light positions, the fare structure, what the stop looks like.', hint: 'Would it change the arrival time shown?' },
  { id: 'cs-c-0180', points: ['2.1.1b'], kind: 'definition', front: 'Define decomposition.', back: 'Breaking a large problem down into smaller sub-problems, each of which can be solved on its own.' },
  { id: 'cs-c-0181', points: ['2.1.1b'], kind: 'list', front: 'Give two benefits of decomposing a problem before writing a program. [2]', back: 'Any two: each part is easier to solve; parts can be shared between people; each part can be tested on its own; parts can be reused elsewhere.', items: ['Each smaller problem is easier to understand and solve', 'Different people can work on different parts at the same time', 'Each part can be tested separately, so bugs are easier to find', 'A solved sub-problem can be reused in another program'] },
  { id: 'cs-c-0182', points: ['2.1.1c'], kind: 'definition', front: 'Define algorithmic thinking.', back: 'Working out the precise, ordered steps that solve a problem — and that would solve it again with different inputs.' },
  { id: 'cs-c-0183', points: ['2.1.1c'], kind: 'compare', front: 'Why is “play a good move” not an algorithm, when “if the centre square is empty, take it” is?', back: 'An algorithm must be followable without any judgement of your own. “A good move” requires the follower to decide what good means; the second version does not.' },
  { id: 'cs-c-0184', points: ['2.1.1a', '2.1.1b'], kind: 'compare', front: 'Abstraction or decomposition — what is the difference?', back: 'Decomposition breaks a problem UP into smaller sub-problems. Abstraction strips detail OUT of the problem. One is about size, the other is about detail.' },
  { id: 'cs-c-0185', points: ['2.1.2b'], kind: 'definition', front: 'What does a structure diagram show?', back: 'How a problem breaks down into sub-problems: the whole problem in a box at the top, its sub-problems branching below it.' },
  { id: 'cs-c-0186', points: ['2.1.2b'], kind: 'list', front: 'What are the three rules that earn or lose marks on a structure diagram?', back: 'One job per box; every box joined to its parent; no arrows.', items: ['Every box does exactly one job — if the label needs “and”, split it', 'Every box is connected to the box it came from', 'NO arrows — a structure diagram shows structure, not order'] },
  { id: 'cs-c-0187', points: ['2.1.2b'], kind: 'compare', front: 'Structure diagram or flowchart — which has arrows, and why?', back: 'The flowchart. It shows the order steps happen in. A structure diagram shows what a problem is made of, so arrows are wrong and cost marks.' },
  { id: 'cs-c-0188', points: ['2.1.2b'], kind: 'recall', front: 'Decompose a vending machine into level 2.', back: 'Take payment, choose product, dispense product, give change.', items: ['Take payment', 'Let the customer choose a product', 'Dispense the product', 'Give change'] },
  { id: 'cs-c-0189', points: ['2.1.2b'], kind: 'recall', front: 'Break “give the right change” down further. Why is it harder than it looks?', back: 'Work out the amount owed, select which coins to return, and handle the case where the machine cannot make the exact change — refusing the sale or asking for a different amount.' },
  { id: 'cs-c-0190', points: ['2.1.1a', '2.1.1b', '2.1.1c'], kind: 'recall', front: 'A 6-mark question asks how all three principles would be used on an unfamiliar program. What loses half the marks?', back: 'Giving textbook definitions and never mentioning the problem in the question. It is marked on application: two points per principle, each one about that specific program.' },
  { id: 'cs-c-0191', points: ['2.1.1a'], kind: 'recall', front: 'When you write about abstraction in an exam, what must you always name?', back: 'The purpose. Detail can only be “unnecessary” relative to what the thing is for.' },

  // --- 2.2.1 programming fundamentals + 2.3.2c errors (booklet Part 3) --------
  { id: 'cs-c-0192', points: ['2.2.1a'], kind: 'code', front: 'What does print(7 + 3) output?', back: '10 — the numbers are outside quotation marks, so Python works the sum out.' },
  { id: 'cs-c-0193', points: ['2.2.1a'], kind: 'code', front: 'What does print("7 + 3") output?', back: '7 + 3 — it is inside quotation marks, so it is text and is printed exactly as written.' },
  { id: 'cs-c-0194', points: ['2.2.1a'], kind: 'code', front: 'What does print("7" + "3") output?', back: '73 — both are strings, so the + joins them together rather than adding them.', hint: 'Two pieces of text, not two numbers.' },
  { id: 'cs-c-0195', points: ['2.2.1a'], kind: 'code', front: 'What does print("=" * 20) do, and why is it better than typing twenty equals signs?', back: 'It prints the = character twenty times. It is better because the width is written once: change the 20 and every banner changes, and you cannot miscount.' },
  { id: 'cs-c-0196', points: ['2.2.1a'], kind: 'definition', front: 'What is a comment used for? [2]', back: 'It is ignored by the computer and changes nothing about how the program runs. It is there to explain the code to a human, making the program easier to understand and maintain later.' },
  { id: 'cs-c-0197', points: ['2.2.1a'], kind: 'definition', front: 'What is a variable?', back: 'A named location in memory whose value can change while the program is running.' },
  { id: 'cs-c-0198', points: ['2.2.1a'], kind: 'compare', front: 'Variable or constant — what is the difference, and why use a constant?', back: 'A variable’s value can change while the program runs; a constant’s cannot. A constant means the value is written once and named, so it cannot be mistyped in one place out of twenty.' },
  { id: 'cs-c-0199', points: ['2.2.1a'], kind: 'code', front: 'In code, what does age = age + 1 actually mean?', back: 'Age BECOMES the old value of age plus one. The equals sign is assignment, not a statement that the two sides are equal.' },
  { id: 'cs-c-0200', points: ['2.3.2c'], kind: 'definition', front: 'What is a syntax error?', back: 'Code that breaks the grammatical rules of the language, so it cannot be translated or run at all — a missing bracket or quotation mark. Python reports it with a line number.' },
  { id: 'cs-c-0201', points: ['2.3.2c'], kind: 'definition', front: 'What is a logic error?', back: 'Code that runs perfectly but produces the wrong output. Nothing reports it — only testing finds it.' },
  { id: 'cs-c-0202', points: ['2.3.2c'], kind: 'compare', front: 'How do you tell a syntax error from a logic error in one question?', back: 'Does the program run at all? If it will not run, it is a syntax error. If it runs and gives the wrong answer, it is a logic error.' },
  { id: 'cs-c-0203', points: ['2.3.2c'], kind: 'code', front: 'Python says: NameError: name \'Print\' is not defined. What is wrong?', back: 'The capital P. Python is case sensitive and the function is print, in lower case.' },
  { id: 'cs-c-0204', points: ['2.3.2c'], kind: 'code', front: 'Python says: NameError: name \'Hello\' is not defined for print(Hello there). What is wrong?', back: 'The text has no quotation marks, so Python treats Hello as a variable name and cannot find one. It should be print("Hello there").' },
  { id: 'cs-c-0205', points: ['2.3.2c'], kind: 'recall', front: 'An error message is several lines long. Which line do you read first?', back: 'The last one — it names the problem. Then look at the line number to find where.' },
  { id: 'cs-c-0206', points: ['2.2.1a'], kind: 'recall', front: 'Explain one reason a programmer saves code in a file rather than typing it into the shell. [2]', back: 'A saved file is stored permanently, so the program can be run, edited and tested again later. Anything typed into the shell is lost as soon as it is closed.' },
  { id: 'cs-c-0207', points: ['2.2.1a'], kind: 'code', front: 'Write the Python that outputs exactly:\nName: Ada\nAge: 36', back: 'print("Name: Ada")\nprint("Age: 36")', hint: 'Two lines of output means two print statements — or one with \\n.' },
]
